EvalData data = EvalData.fromEnvironment();
Path treebank = data.dataset("ud");                 // <eval root>/ud
Path chunker = data.model("en-chunker.bin");        // <models>/en-chunker.bin

EvalReport report = EvalReport.atLeast("upos.accuracy", "ud", "bilstm", 0.953, 0.85);
EvalReport.write(Path.of("target", "eval-reports", "ud.tsv"), List.of(report));
